package workbench.ksp.app.l04

import workbench.ksp.app.l04.van.LoadBuilder

// Lesson 4, Try it in the real build: every builder here was generated by KSP during the build.
//   ./gradlew :ksp:app:demo -Pmain=workbench.ksp.app.l04.MoveDayKt
fun main() {
    val lamp = LampBuilder().name("desk lamp").bulbs(1).shade(null).build()
    val plates = BoxBuilder().label("plates").room("kitchen").weightGrams(4200).fragile(true).build()
    val load = LoadBuilder().first(plates).spares(listOf(null, plates)).build()
    val drawer = KitchenDrawerBuilder().label("spoons").handles(2).build()
    val crate = CrateBuilder().`in`("hall").`object`("mirror").build()

    println(lamp)
    println(plates)
    println("load: first=${load.first.label}, spares=${load.spares?.size}")
    println(drawer)
    println("crate: in=${crate.`in`}, object=${crate.`object`}")
    // a property with a default is still required: KSP saw that Plant has a default, not what it is
    println(runCatching { PlantBuilder().kind("fern").potLitres(2.5).build() }.exceptionOrNull()?.message)
}
